#!/usr/bin/env bash
# Runs on master. node_exporter is already on every node (cloud-init).
# Installs Prometheus (1 s scrape) and Grafana on master.
source "$(dirname "$0")/lib.sh"
export DEBIAN_FRONTEND=noninteractive

log "Prometheus"
sudo -E apt-get install -y -qq prometheus >/dev/null
TARGETS=$(for n in $NODES; do printf "'%s:9100', " "$n"; done)
TARGETS="[${TARGETS%, }]"
sudo tee /etc/prometheus/prometheus.yml >/dev/null <<EOF
# Generated by infra/linux/install-monitoring.sh
global:
  scrape_interval: 1s
  evaluation_interval: 15s
scrape_configs:
  - job_name: node
    static_configs:
      - targets: $TARGETS
  - job_name: prometheus
    scrape_interval: 5s
    static_configs:
      - targets: ['localhost:9090']
EOF
echo 'ARGS="--storage.tsdb.retention.time=60d"' | sudo tee /etc/default/prometheus >/dev/null
sudo systemctl enable prometheus >/dev/null 2>&1
sudo systemctl restart prometheus

install_grafana() {
  if [[ ! -x /usr/sbin/grafana-server ]]; then
    sudo mkdir -p /etc/apt/keyrings
    curl -fsSL https://apt.grafana.com/gpg.key | sudo gpg --dearmor --yes -o /etc/apt/keyrings/grafana.gpg
    echo "deb [signed-by=/etc/apt/keyrings/grafana.gpg] https://apt.grafana.com stable main" \
      | sudo tee /etc/apt/sources.list.d/grafana.list >/dev/null
    sudo apt-get update -qq
    sudo -E apt-get install -y -qq grafana >/dev/null
  fi
  sudo tee /etc/grafana/provisioning/datasources/prometheus.yml >/dev/null <<'EOF'
apiVersion: 1
datasources:
  - name: Prometheus
    uid: prometheus
    type: prometheus
    access: proxy
    url: http://localhost:9090
    isDefault: true
    jsonData:
      timeInterval: 1s
EOF
  sudo tee /etc/grafana/provisioning/dashboards/cluster.yml >/dev/null <<'EOF'
apiVersion: 1
providers:
  - name: cluster
    folder: Cluster
    type: file
    options:
      path: /var/lib/grafana/dashboards
EOF
  sudo mkdir -p /var/lib/grafana/dashboards
  # "Node Exporter Full" community dashboard (id 1860)
  if curl -fsSL https://grafana.com/api/dashboards/1860/revisions/latest/download -o /tmp/node-full.json; then
    sed 's/\${DS_PROMETHEUS}/prometheus/g' /tmp/node-full.json | sudo tee /var/lib/grafana/dashboards/node-exporter-full.json >/dev/null
  else
    warn "could not download the Node Exporter Full dashboard (Grafana still works)"
  fi
  # our own dashboard: the 4 VMs on the same panels; it is also the home page
  sudo install -m 644 "$CONF_DIR/grafana/cluster-overview.json" /var/lib/grafana/dashboards/cluster-overview.json
  sudo chown -R grafana:grafana /var/lib/grafana/dashboards
  grep -q GF_DASHBOARDS_DEFAULT_HOME_DASHBOARD_PATH /etc/default/grafana-server 2>/dev/null || \
    echo 'GF_DASHBOARDS_DEFAULT_HOME_DASHBOARD_PATH=/var/lib/grafana/dashboards/cluster-overview.json' \
      | sudo tee -a /etc/default/grafana-server >/dev/null
  sudo systemctl enable grafana-server >/dev/null 2>&1
  sudo systemctl restart grafana-server
}

log "Grafana"
install_grafana || warn "Grafana installation failed - it is optional, Prometheus keeps all the data"
log "Monitoring ready: Prometheus :9090, Grafana :3000 (admin/admin)"
